import React, { useState } from 'react';
import { Moon, Sun, UserCircle } from 'lucide-react';
import MyEshLogo from '...c';
import NavItem from './NavItem';
import NavItemMobile from './NavItemMobile';

const Navbar = ({ user, onNavigate, onSignOut, authInstance, toggleTheme, currentTheme }) => {
    const [showDropdown, setShowDropdown] = useState(false);
    const displayName = user?.name || (user?.email?.split('@')[0]) || 'Guest';

    const navLinks = [
        { page: 'dashboard', label: 'Dashboard' },
        { page: 'maps', label: 'Maps' },
        { page: 'priceData', label: 'Price Data' },
        { page: 'newsAndInsights', label: 'News & Insights' },
        { page: 'knowledgeHub', label: 'Knowledge Hub' },
        { page: 'sourcingHub', label: 'Sourcing Hub' },
        { page: 'support', label: 'Support' },
    ];

    const handleSignOut = async () => {
        if (!authInstance) return;
        try {
            await onSignOut(authInstance);
            onNavigate('login');
        } catch (err) {
            console.error("Sign out error:", err);
        }
    };

    return (
        <nav className="bg-white dark:bg-gray-900 shadow-md sticky top-0 z-50 border-b dark:border-gray-700">
            <div className="container mx-auto px-4">
                <div className="flex justify-between items-center h-16">
                    <div onClick={() => onNavigate('dashboard')} className="flex items-center cursor-pointer">
                        <MyEshLogo />
                    </div>
                    <div className="hidden lg:flex space-x-4">
                        {navLinks.map(link => (
                            <NavItem key={link.page} onClick={() => onNavigate(link.page)} label={link.label} />
                        ))}
                    </div>
                    <div className="flex items-center space-x-4">
                        <button onClick={toggleTheme} className="p-2 text-gray-500 hover:text-gray-900 dark:text-gray-300 dark:hover:text-white">
                            {currentTheme === 'light' ? <Moon size={20} /> : <Sun size={20} />}
                        </button>
                        <div className="relative">
                            <button onClick={() => setShowDropdown(!showDropdown)} className="p-2 text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-full">
                                <UserCircle size={24} />
                                <span className="ml-2 hidden md:inline">{displayName}</span>
                            </button>
                            {showDropdown && (
                                <div className="absolute right-0 mt-2 w-48 bg-white dark:bg-gray-800 shadow-lg rounded-md z-20 py-1">
                                    <button onClick={() => { onNavigate('profile'); setShowDropdown(false); }} className="w-full text-left px-4 py-2 hover:bg-gray-100 dark:hover:bg-gray-700">Profile</button>
                                    <button onClick={handleSignOut} className="w-full text-left px-4 py-2 hover:bg-gray-100 dark:hover:bg-gray-700">Sign Out</button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
                <div className="lg:hidden flex overflow-x-auto py-2 border-t dark:border-gray-700">
                    {navLinks.map(link => (
                        <NavItemMobile key={link.page} onClick={() => onNavigate(link.page)} label={link.label} />
                    ))}
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
